import re,json,html
from urllib.parse import urlsplit,unquote

def song_ref(value):
    value=html.unescape((value or '').strip()).rstrip('.,，。；;）)]】>')
    if re.fullmatch(r'\d{4,20}',value):return {'kind':'id','id':value,'url':'https://music.163.com/song?id='+value}
    if not re.match(r'^https?://',value):return None
    try:
        p=urlsplit(value);host=(p.hostname or '').lower()
        if p.username or p.password or p.port not in (None,80,443):return None
    except ValueError:return None
    if host=='163cn.tv' and p.path not in ('','/'):return {'kind':'short','id':'','url':'https://163cn.tv'+p.path}
    if host not in ('music.163.com','y.music.163.com','m.music.163.com'):return None
    path=unquote(p.path+'?'+p.query+'#'+p.fragment)
    if not re.search(r'(?:/|#)(?:song(?:\b|/)|outchain/player)',path):return None
    ids=re.findall(r'(?:[?&#]|\b)id=(\d{4,20})(?:\D|$)',path)
    if not ids or ('outchain/player' in path and re.search(r'type=(?!2\b)\d+',path)):return None
    sid=ids[0];return {'kind':'id','id':sid,'url':'https://music.163.com/song?id='+sid}

def main(userinput_query:str,song_url:str)->dict:
    q=html.unescape((userinput_query or '').strip()).replace('https\\://','https://').replace('http\\://','http://')
    field=html.unescape((song_url or '').strip()).replace('https\\://','https://')
    urls=re.findall(r'https?://[^\s<>"\u3000，。；！？、（）《》\[\]\)]+',q)
    refs=[];music_urls=[]
    for u in urls:
        r=song_ref(u)
        if r:refs.append(r);music_urls.append(u)
    f=song_ref(field) if field else None
    error=''
    if field and not f:error='song_url暂支持网易云歌曲链接、163cn.tv短链或歌曲ID；其他参考请保留在描述中。'
    if f:refs.insert(0,f)
    # 标准链接与短链共存时留待解析核验，不因同曲两种写法直接判冲突。
    ids={r['id'] for r in refs if r['kind']=='id'};shorts={r['url'] for r in refs if r['kind']=='short'}
    if len(ids)>1 or len(shorts)>1 or (ids and shorts):error='检测到多个歌曲引用，请只保留本次参考的一首链接。'
    r=refs[0] if refs else {'kind':'none','id':'','url':''}
    clean=q
    for u in music_urls:clean=clean.replace(u,' ')
    metadata=[]
    pattern=r'分享\s*([^\n《》]{1,120}?)\s*的(?:单曲|歌曲)\s*《([^》\n]+)》'
    def share(m):
        metadata.append({'artist':m.group(1).strip(),'title':m.group(2).strip(),'origin':'platform_share_identity_only'})
        return ' '
    clean=re.sub(pattern,share,clean)
    clean=re.sub(r'[（(]\s*(?:来自\s*)?@?网易云音乐\s*[）)]',' ',clean)
    clean=re.sub(r'\s+',' ',clean).strip(' ，,;；')
    return {'request':json.dumps({'song_share_metadata':metadata,'user_requirements_text':clean,'identity_only_warning':'分享歌名与艺术家用于歌曲定位，不是画面要求，也不自动作为情绪或媒介依据。'},ensure_ascii=False),'raw_query':q,'ref':json.dumps(r,ensure_ascii=False),'input_error':error}

"""Build OpenAI-compatible model requests without reading or exposing API keys."""

import ipaddress
import json
import re
from urllib.parse import urlsplit


def endpoint(base_url):
    base = str(base_url or "").strip().rstrip("/")
    parsed = urlsplit(base)
    host = (parsed.hostname or "").lower()
    valid = (parsed.scheme == "https" and host and not parsed.username
             and not parsed.password and not parsed.query and not parsed.fragment)
    if host == "localhost" or host.endswith((".localhost", ".local", ".internal")):
        valid = False
    try:
        if not ipaddress.ip_address(host).is_global:
            valid = False
    except ValueError:
        pass
    if not valid:
        raise ValueError("MODEL_API_BASE_URL 必须是公开 HTTPS 模型服务地址，不含账号、查询参数或片段。")
    return base if parsed.path.rstrip("/").endswith("/chat/completions") else base + "/chat/completions"


def request_payload(templates, values, model, base_url, image_url=""):
    model = str(model or "").strip()
    if not model or len(model) > 200 or any(ord(c) < 32 for c in model):
        raise ValueError("请配置有效的文本或视觉模型名称。")

    def substitute(match):
        selector = match.group(1)
        if selector not in values:
            raise ValueError("模型请求缺少上游输入变量。")
        value = values[selector]
        return value if isinstance(value, str) else json.dumps(value, ensure_ascii=False)

    messages = [{"role": part["role"], "content": re.sub(
        r"\{\{#([^#]+)#\}\}", substitute, part["text"])} for part in templates]
    if image_url:
        parsed = urlsplit(image_url)
        host = (parsed.hostname or "").lower()
        if (parsed.scheme != "https" or parsed.username or parsed.password
                or not any(host == domain or host.endswith("." + domain)
                           for domain in ("music.126.net", "music.163.com"))):
            raise ValueError("视觉参考仅接受已核验的公开音乐平台封面地址。")
        users = [message for message in messages if message["role"] == "user"]
        if not users:
            raise ValueError("视觉请求缺少用户消息。")
        users[-1]["content"] = [
            {"type": "text", "text": users[-1]["content"]},
            {"type": "image_url", "image_url": {"url": image_url, "detail": "high"}},
        ]
    body = {"model": model, "messages": messages, "stream": False,
            "response_format": {"type": "json_object"}}
    return {"body": json.dumps(body, ensure_ascii=False), "endpoint": endpoint(base_url)}


def completion_result(body, status_code, fallback=None):
    # Remote errors may echo input or credentials. Never include their body in errors.
    result = None
    try:
        data = json.loads(body)
        choices = data.get("choices", [])
        if int(status_code) == 200 and choices and isinstance(choices[0], dict):
            choice = choices[0]
            content = choice.get("message", {}).get("content")
            if choice.get("finish_reason") == "stop" and isinstance(content, str) and content.strip():
                # All original model prompts request a JSON object.
                parsed = json.loads(content)
                if isinstance(parsed, dict):
                    usage = data.get("usage", {})
                    allowed = ("prompt_tokens", "completion_tokens", "total_tokens",
                               "prompt_cache_hit_tokens", "prompt_cache_miss_tokens")
                    usage = {k: v for k, v in usage.items()
                             if k in allowed and isinstance(v, int) and not isinstance(v, bool) and v >= 0}
                    result = {"text": content, "usage": json.dumps(usage), "api_status": "ok"}
    except (ValueError, TypeError, AttributeError, OverflowError):
        pass
    if result is not None:
        return result
    if fallback is not None:
        return {"text": fallback, "usage": "{}", "api_status": "unavailable"}
    raise ValueError("模型 API 调用未成功或未返回完整 JSON，请检查环境变量、模型支持及私有运行记录。")


def main(body: str, status_code: int) -> dict:
    return completion_result(body,status_code,None)

import json,re
from urllib.parse import quote

def obj(raw):
    text=re.sub(r'<think>.*?</think>','',raw or '',flags=re.S).strip()
    text=re.sub(r'^```(?:json)?\s*','',text);text=re.sub(r'\s*```$','',text)
    try:d=json.loads(text)
    except Exception:
        pos=text.find('{')
        try:d=json.JSONDecoder().raw_decode(text[pos:])[0] if pos>=0 else None
        except Exception:d=None
    if not isinstance(d,dict):raise ValueError('意图解析格式异常；请重试。')
    return d

def main(raw:str,ref:str,input_error:str)->dict:
    d=obj(raw);r=json.loads(ref);title=str(d.get('song_title') or '').strip();artist=str(d.get('song_artist') or '').strip();error=input_error or ''
    if d.get('input_conflicts'):error=error or '画面要求存在冲突：'+json.dumps(d['input_conflicts'],ensure_ascii=False)+'。请明确希望采用哪一项。'
    d['constraints']=[x for x in d.get('constraints') or [] if isinstance(x,dict) and x.get('quote')]
    for i,c in enumerate(d['constraints']):c['id']='U'+str(i+1)
    if r['kind']=='id':url='https://music.163.com/api/song/detail/?id='+r['id']+'&ids=%5B'+r['id']+'%5D'
    elif r['kind']=='short':url=r['url']
    elif title:url='https://music.163.com/api/search/get?s='+quote(title+' '+artist)+'&type=1&limit=8&offset=0'
    else:url='https://music.163.com/api/search/get?s=__missing_song__&type=1&limit=1';error=error or '请提供歌曲名称或分享链接；song_url可以选填。'
    d['song_title']=title;d['song_artist']=artist
    return {'intent':json.dumps(d,ensure_ascii=False),'lookup_url':url,'error':error}

import json,re,html
from urllib.parse import quote
def norm(x):return re.sub(r'[\W_]+','',str(x).lower())
def main(body:str,ref:str,intent:str,error:str)->dict:
