    locks=[]
    for c in constraints:
        q=str(c.get('quote') or '').strip();target=str(c.get('target') or '按用户原意');strength={'required':'明确要求','preferred':'偏好','forbidden':'禁止项'}.get(c.get('strength'),'要求')
        if q:locks.append(strength+'（'+target+'）：'+q)
