    missing=0;retained_norm={re.sub(r'\W+','',p['text']).casefold() for p in state['accepted']}
    for cid,p in pool.items():
        x=labels.get(cid) or {};kind=x.get('kind');useful=x.get('useful') is True and kind in KINDS
        if not x:missing+=1
